alter table public.orders add column package_tier text not null default 'basic' check(package_tier in ('basic','advanced','vip')); create function public.submit_guest_package_order(p_service text,p_tier text,p_name text,p_phone text,p_details text,p_ref text default null) returns uuid language plpgsql security definer set search_path='' as $$declare result uuid;price integer;begin if p_tier is null or p_tier not in ('basic','advanced','vip') then raise exception 'Invalid tier';end if;if length(trim(coalesce(p_name,''))) not between 2 and 100 or length(trim(coalesce(p_phone,''))) not between 7 and 25 or length(trim(coalesce(p_details,''))) not between 1 and 3000 then raise exception 'Invalid details';end if;select case when p_tier='basic' then s.price_fils else p.price_fils end into price from public.services s left join public.service_packages p on p.service_id=s.id and p.tier=p_tier where s.id=p_service and s.active;if price is null then raise exception 'Unavailable';end if;insert into public.orders(user_id,service_id,price_fils,package_tier,details,referral_code) values(null,p_service,price,p_tier,jsonb_build_object('name',p_name,'phone',p_phone,'text',p_details),case when p_ref ~ '^[a-f0-9]{32}$' then p_ref else null end) returning id into result;return result;end$$;revoke all on function public.submit_guest_package_order(text,text,text,text,text,text) from public;grant execute on function public.submit_guest_package_order(text,text,text,text,text,text) to anon,authenticated;